CREATE SCHEMA usa_atlas;
CREATE TABLE usa_atlas.catalog_field (catalog_field_id text PRIMARY KEY, catalog_label text NOT NULL, planned_state text NOT NULL, rate_limit_profile text NOT NULL, source_release text NOT NULL, contract jsonb NOT NULL, contract_sha256 character(64) NOT NULL);
CREATE TABLE usa_atlas.ingest_run (ingest_id uuid PRIMARY KEY, source text NOT NULL, artifact_path text NOT NULL, artifact_sha256 character(64) NOT NULL, contract_sha256 character(64) NOT NULL, row_count bigint NOT NULL, started_at timestamptz NOT NULL, completed_at timestamptz, status text NOT NULL, error_code text);
CREATE TABLE usa_atlas.observation (geo_id text NOT NULL, geo_type text NOT NULL, period text NOT NULL, field_id text NOT NULL, catalog_field_id text NOT NULL REFERENCES usa_atlas.catalog_field, value double precision NOT NULL, unit text NOT NULL, source text NOT NULL, source_release text NOT NULL, source_url text NOT NULL, methodology_note text NOT NULL, retrieved_at timestamptz NOT NULL, ingest_id uuid NOT NULL REFERENCES usa_atlas.ingest_run, PRIMARY KEY (geo_id,period,field_id,source_release));
